import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

interface VendorBody {
  id: string;
  name: string;
  status: string;
}

interface DocumentBody {
  id: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  kind: string;
  status: string;
}

const RUN_ID = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

async function waitForExtraction(member: APIRequestContext, documentId: string): Promise<ExtractionBody> {
  await expect
    .poll(
      async () => {
        const response = await member.get(`/api/documents/${documentId}`);
        const doc = await expectStatus<DocumentBody>(response, 200);
        return doc.status;
      },
      { timeout: 60_000, intervals: [500, 1_000, 2_000] },
    )
    .toBe("extracted");

  const response = await member.get(`/api/documents/${documentId}/extraction`);
  return expectStatus<ExtractionBody>(response, 200);
}

test.describe("vendor lifecycle", () => {
  test(
    "A vendor that was sent back can be edited again",
    { tag: "@LIF-09" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor with a unique name.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const originalName = `LIF-09 Vendor ${RUN_ID}`;

      const created = await expectStatus<VendorBody>(
        await member.post("/api/vendors", {
          data: {
            name: originalName,
            category: "services",
            contact_email: `lif09-${RUN_ID}@example.test`,
          },
        }),
        201,
      );

      // Arrange: the member uploads a contract, which gets extracted.
      const upload = await expectStatus<{ id: string; kind: string }>(
        await member.post(`/api/vendors/${created.id}/documents`, {
          multipart: {
            kind: "contract",
            file: {
              name: `contract-${RUN_ID}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 contract ${RUN_ID}`),
            },
          },
        }),
        201,
      );
      const extraction = await waitForExtraction(member, upload.id);
      expect(extraction.kind).toBe("contract");

      // Arrange: a reviewer rejects the contract extraction, sending the vendor back.
      const decided = await expectStatus<ExtractionBody>(
        await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
          data: { decision: "reject", note: `LIF-09 rejection ${RUN_ID}` },
        }),
        200,
      );
      expect(decided.status).toBe("rejected");

      // Act: the member changes the vendor's name.
      const newName = `${originalName} Renamed`;
      const response = await member.patch(`/api/vendors/${created.id}`, {
        data: { name: newName },
      });

      // Assert: the update succeeds and the response carries the new name.
      const updated = await expectStatus<VendorBody>(response, 200);
      expect(updated.name).toBe(newName);

      // Assert: the new name is persisted.
      const fetched = await expectStatus<VendorBody>(
        await member.get(`/api/vendors/${created.id}`),
        200,
      );
      expect(fetched.name).toBe(newName);
    },
  );
});
